// 中文说明：vConsole 运行期开关。不依赖 vite-plugin-vconsole 的构建期注入（该插件仅 test 环境开启），
// 生产包也能通过隐藏手势手动唤起调试面板。动态 import 保证不进入首屏包体。

/** 面板是否已创建（仅在 H5 有意义） */
export function isVConsoleActive(): boolean {
  return typeof window !== 'undefined' && !!window.__vConsole
}

/**
 * 切换 vConsole 调试面板。
 * @returns 切换后是否为「已开启」
 */
export async function toggleVConsole(): Promise<boolean> {
  // #ifdef H5
  try {
    // 已开启：销毁面板并清除引用，保证下次十连击能重新打开
    if (window.__vConsole) {
      try {
        window.__vConsole.destroy()
      } catch (e) {
        // destroy 失败不阻断关闭流程
      }
      delete window.__vConsole
      return false
    }

    const { default: VConsole } = await import('vconsole')
    const instance = new VConsole({
      theme: 'dark',
      defaultPlugins: ['system', 'network', 'element', 'storage'],
      log: { maxLogNumber: 2000 },
      network: { maxNetworkNumber: 500 },
    })
    window.__vConsole = instance
    instance.show()
    return true
  }
  catch (err) {
    console.warn('[vconsole] 初始化失败：', err)
    return false
  }
  // #endif
  // #ifndef H5
  return false
  // #endif
}

/**
 * 统一日志出口：面板开启时写入 vConsole，否则回落控制台。
 * 中文说明：参数保持原样传递（对象引用不序列化），vConsole 中可折叠展开查看完整入参与响应。
 */
export function vlog(...args: any[]): void {
  // #ifdef H5
  const vc = typeof window !== 'undefined' ? window.__vConsole : null
  if (vc && typeof vc.log === 'function') {
    vc.log(...args)
    return
  }
  // #endif
  console.log(...args)
}

// 中文说明：多次连击判定工具，用于隐藏调试入口。
// 不使用 setTimeout，避免页面隐藏/卸载后遗留定时器；超窗口的旧记录在下次点击时丢弃。

export interface TapCounterOptions {
  /** 触发所需次数，默认 10 */
  times?: number
  /** 连击时间窗口（毫秒），默认 2000 */
  windowMs?: number
  /** 达到次数后的回调 */
  onTrigger: () => void
}

export interface TapCounter {
  tap: () => void
  /** 当前窗口内已累计次数，便于调试 */
  count: () => number
  reset: () => void
}

export function createTapCounter(options: TapCounterOptions): TapCounter {
  const times = Math.max(2, options.times ?? 10)
  const windowMs = Math.max(200, options.windowMs ?? 2000)
  let stamps: number[] = []

  return {
    tap() {
      const now = Date.now()
      stamps = stamps.filter(t => now - t <= windowMs)
      stamps.push(now)

      if (stamps.length >= times) {
        stamps = []
        options.onTrigger()
      }
    },
    count() {
      const now = Date.now()
      stamps = stamps.filter(t => now - t <= windowMs)
      return stamps.length
    },
    reset() {
      stamps = []
    },
  }
}

