import type { CustomRequestOptions } from '@/http/types'
import { getEnvBaseUrl, getApiPrefix } from '@/utils'
import { vlog } from '@/utils/vconsole'
import { stringifyQuery } from './tools/queryString'

// 请求基准地址
const baseUrl = getEnvBaseUrl()

// 中文说明：请求入参登记表。请求发出时只登记不打印，响应到达后与响应合并成一条日志。
interface PendingRequest {
  url: string
  method: string
  query?: Record<string, any>
  data?: any
  header?: Record<string, any>
  startTime: number
}
const pendingRequests = new Map<string, PendingRequest>()
let requestSeq = 0
// 残留清理阈值：超时或被中断的请求不会回调，防止登记表持续增长
const PENDING_TTL = 5 * 60 * 1000

/** 敏感字段打码，避免调试日志外泄凭证与个人信息 */
const SENSITIVE_KEY = /^(authorization|token|password|passwd|pwd|idcard|idno|phone|mobile|tel|accessToken|secret)$/i
function maskSensitive(input: any, depth = 0): any {
  if (depth > 6 || input === null || typeof input !== 'object') return input
  if (Array.isArray(input)) return input.map(item => maskSensitive(item, depth + 1))
  const out: Record<string, any> = {}
  for (const key of Object.keys(input)) {
    const value = input[key]
    if (SENSITIVE_KEY.test(key)) {
      out[key] = typeof value === 'string' && value.length > 6 ? `${value.slice(0, 3)}***${value.slice(-2)}` : '***'
    }
    else {
      out[key] = maskSensitive(value, depth + 1)
    }
  }
  return out
}

function cleanupPending() {
  const now = Date.now()
  for (const [id, item] of pendingRequests) {
    if (now - item.startTime > PENDING_TTL) pendingRequests.delete(id)
  }
}

/**
 * 打印一次接口请求的入参与响应（聚合成一条日志）。
 * 中文说明：业务层 success/fail 回调中调用，保证一次请求只产生一条日志。
 */
export function logResponse(options: CustomRequestOptions, res?: any, err?: any) {
  try {
    cleanupPending()
    const reqId = (options as any).__reqId as string | undefined
    let pending = reqId ? pendingRequests.get(reqId) : undefined
    // 兑底：拿不到 __reqId 时，按 url+method 匹配最近一条未完成登记
    if (!pending) {
      const url = options.url || ''
      const method = (options.method || 'GET').toUpperCase()
      let latestTime = -1
      for (const [id, item] of pendingRequests) {
        if (item.url === url && item.method === method && item.startTime > latestTime) {
          latestTime = item.startTime
          pending = item
          ;(options as any).__reqId = id
        }
      }
    }

    const startTime = pending?.startTime ?? Date.now()
    const duration = Date.now() - startTime
    const method = pending?.method || (options.method || 'GET').toUpperCase()
    const url = pending?.url || options.url || ''
    const statusCode = res ? res.statusCode : 0

    const title = `[API] ${method} ${url} ${err ? 'FAIL' : statusCode} ${duration}ms`
    const payload: Record<string, any> = {
      入参: {
        query: maskSensitive(pending?.query),
        data: maskSensitive(pending?.data),
        header: maskSensitive(pending?.header),
      },
      响应: err
        ? { error: String(err?.errMsg || err?.message || err) }
        : { statusCode, body: maskSensitive(res?.data) },
    }

    // 一次请求只用一条日志；面板开启时进 vConsole，否则回落控制台
    vlog(title, payload)

    const id = (options as any).__reqId as string | undefined
    if (id) pendingRequests.delete(id)
  }
  catch (e) {
    // 日志异常不影响业务主流程
    console.warn('[API] 日志输出失败', e)
  }
}

