tool_input.content:
import { chromium } from '@playwright/test'

const URL = 'http://localhost:9000/#/pages-my/customer/index'

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true })
const page = await ctx.newPage()

const logs = []
page.on('console', (msg) => logs.push(msg.text()))
page.on('pageerror', (e) => logs.push('[PAGEERROR] ' + e.message))

await page.goto(URL, { waitUntil: 'networkidle' })
await page.waitForTimeout(2500)

const avatar = page.locator('img').first()
await avatar.waitFor({ state: 'visible', timeout: 15000 })

// 1) 点击 9 下不应唤起
for (let i = 0; i < 9; i++) {
  await avatar.click({ force: true })
  await page.waitForTimeout(80)
}
const after9 = await page.evaluate(() => !!window.__vConsole)

// 2) 第 10 下应唤起
await avatar.click({ force: true })
await page.waitForTimeout(2500)
const after10 = await page.evaluate(() => !!window.__vConsole)
const panelVisible = await page.evaluate(() => {
  const el = document.querySelector('#__vconsole')
  return !!el
})

// 3) 再点 10 下关闭
for (let i = 0; i < 10; i++) {
  await avatar.click({ force: true })
  await page.waitForTimeout(80)
}
await page.waitForTimeout(1200)
const afterClose = await page.evaluate(() => !!window.__vConsole)

// 4) 再点 10 下能重新打开
for (let i = 0; i < 10; i++) {
  await avatar.click({ force: true })
  await page.waitForTimeout(80)
}
await page.waitForTimeout(2500)
const afterReopen = await page.evaluate(() => !!window.__vConsole)

console.log(JSON.stringify({ after9, after10, panelVisible, afterClose, afterReopen }, null, 2))
console.log('=== API LOGS ===')
for (const l of logs) if (l.includes('[API]') || l.includes('PAGEERROR')) console.log(l.slice(0, 400))

await browser.close()

